(function() {
    "use strict";
    
    // 粒子类
    class Particle {
        constructor(x, y, type = 'trail') {
            this.x = x;
            this.y = y;
            this.type = type;
            
            // 根据类型设置不同的初始属性
            if (type === 'explosion') {
                this.size = Math.random() * 5 + 2;
                this.speedX = Math.random() * 6 - 3;
                this.speedY = Math.random() * 6 - 3;
                this.color = `rgba(100, 100, 100, ${Math.random() * 0.5 + 0.5})`; // 改为深灰色
                this.life = 1;
                this.decay = Math.random() * 0.02 + 0.01;
            } else if (type === 'float') {
                this.size = Math.random() * 3 + 1;
                this.speedX = Math.random() * 1 - 0.5;
                this.speedY = Math.random() * 1 - 0.5;
                this.color = `rgba(255, 255, 255, ${Math.random() * 0.3 + 0.1})`; // 改为白色，降低透明度
                this.life = 1;
                this.decay = 0; // 漂浮粒子不会消失
            } else {
                this.size = Math.random() * 2 + 1;
                this.speedX = Math.random() * 1 - 0.5;
                this.speedY = Math.random() * 1 - 0.5;
                this.color = `rgba(100, 100, 100, ${Math.random() * 0.4 + 0.5})`; // 改为深灰色
                this.life = 1;
                this.decay = Math.random() * 0.03 + 0.02;
            }
        }
        
        update() {
            this.x += this.speedX;
            this.y += this.speedY;
            this.life -= this.decay;
            
            // 爆炸粒子会有更大的速度衰减
            if (this.type === 'explosion') {
                this.speedX *= 0.95;
                this.speedY *= 0.95;
            }
            
            // 漂浮粒子边界检查
            if (this.type === 'float') {
                if (this.x < 0 || this.x > window.innerWidth) this.speedX *= -1;
                if (this.y < 0 || this.y > window.innerHeight) this.speedY *= -1;
            }
        }
        
        draw(ctx) {
            ctx.globalAlpha = this.life;
            ctx.fillStyle = this.color;
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
            ctx.fill();
            ctx.globalAlpha = 1;
        }
    }
    
    // 鼠标特效控制器
    class MouseEffect {
        constructor() {
            this.canvas = document.createElement('canvas');
            this.ctx = this.canvas.getContext('2d');
            this.particles = [];
            this.mouseX = 0;
            this.mouseY = 0;
            this.hue = 0;
            this.isRunning = false;
            
            this.init();
        }
        
        init() {
            // 设置画布样式
            this.canvas.style.position = 'fixed';
            this.canvas.style.top = '0';
            this.canvas.style.left = '0';
            this.canvas.style.width = '100%';
            this.canvas.style.height = '100%';
            this.canvas.style.pointerEvents = 'none';
            this.canvas.style.zIndex = '999999999';
            
            // 设置画布尺寸
            this.resize();
            
            // 添加到页面
            document.body.appendChild(this.canvas);
            
            // 初始化漂浮粒子
            this.initFloatingParticles();
            
            // 监听事件
            window.addEventListener('resize', () => this.resize());
            window.addEventListener('mousemove', (e) => this.handleMouseMove(e));
            window.addEventListener('click', (e) => this.handleClick(e));
            
            // 开始动画循环
            this.animate();
        }
        
        resize() {
            this.canvas.width = window.innerWidth;
            this.canvas.height = window.innerHeight;
        }
        
        initFloatingParticles() {
            // 创建漂浮粒子
            for (let i = 0; i < 50; i++) {
                const x = Math.random() * window.innerWidth;
                const y = Math.random() * window.innerHeight;
                this.particles.push(new Particle(x, y, 'float'));
            }
        }
        
        handleMouseMove(e) {
            this.mouseX = e.clientX;
            this.mouseY = e.clientY;
            
            // 减少拖尾粒子数量
            if (Math.random() > 0.7) { // 30%的概率产生拖尾粒子
                this.particles.push(new Particle(this.mouseX, this.mouseY, 'trail'));
            }
        }
        
        handleClick(e) {
            // 添加爆炸粒子
            for (let i = 0; i < 30; i++) {
                this.particles.push(new Particle(e.clientX, e.clientY, 'explosion'));
            }
        }
        
        drawConnections() {
            const maxDistance = 120;
            
            for (let i = 0; i < this.particles.length; i++) {
                for (let j = i + 1; j < this.particles.length; j++) {
                    const dx = this.particles[i].x - this.particles[j].x;
                    const dy = this.particles[i].y - this.particles[j].y;
                    const distance = Math.sqrt(dx * dx + dy * dy);
                    
                    if (distance < maxDistance) {
                        const opacity = (1 - distance / maxDistance) * 0.3;
                        this.ctx.strokeStyle = `rgba(100, 100, 100, ${opacity})`; // 改为深灰色
                        this.ctx.lineWidth = 0.5;
                        this.ctx.beginPath();
                        this.ctx.moveTo(this.particles[i].x, this.particles[i].y);
                        this.ctx.lineTo(this.particles[j].x, this.particles[j].y);
                        this.ctx.stroke();
                    }
                }
            }
        }
        
        animate() {
            // 清除画布
            this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
            
            // 更新和绘制粒子
            for (let i = this.particles.length - 1; i >= 0; i--) {
                this.particles[i].update();
                this.particles[i].draw(this.ctx);
                
                // 移除生命周期结束的粒子（漂浮粒子除外）
                if (this.particles[i].life <= 0 && this.particles[i].type !== 'float') {
                    this.particles.splice(i, 1);
                }
            }
            
            // 绘制粒子间的连线
            this.drawConnections();
            
            // 更新色相
            this.hue += 1;
            
            // 继续动画循环
            requestAnimationFrame(() => this.animate());
        }
    }
    
    // 初始化特效
    new MouseEffect();
})();
